export function mountDocuments(root, notebook) {
  const render = () => {
    const matching = notebook.documents.filter(doc => doc.title.toLowerCase().includes(notebook.query.toLowerCase()));
    root.replaceChildren(...matching.map(doc => {
      const link = document.createElement('a');
      link.href = '#document-title'; link.textContent = doc.title;
      link.onclick = event => { event.preventDefault(); notebook.select(doc.id); };
      return link;
    }));
    root.classList.toggle('document-results', matching.length > 0);
    if (!matching.length) root.textContent = 'No documents found';
  };
  notebook.subscribe(event => { if (['search','document'].includes(event)) render(); });
  render();
}

